import Foundation

public struct Item {
    public let price: Double
    public let qty: Int
}

public func calcTotal(items: [Item]) -> Double {
    items.reduce(0) { $0 + $1.price * Double($1.qty) }
}

public func formatPrice(_ amount: Double) -> String {
    String(format: "$%.2f", amount)
}

